package dev.slithergoh.pixelmonradar.client;
import net.minecraft.client.Minecraft;import net.minecraft.network.chat.Component;import net.minecraft.sounds.SoundEvents;import net.minecraft.sounds.SoundSource;import java.util.*;
public final class RareAlerts{private RareAlerts(){}private static final Set<Integer>seen=new HashSet<>();private static int ticks;private static int priority(PokemonInfo p){if(p.shiny())return 100;if(p.legendary()||p.mythical())return 90;if(p.ultraBeast()||p.paradox())return 80;if(p.boss())return 70;return 0;}public static void tick(){if(++ticks%2!=0)return;Minecraft mc=Minecraft.getInstance();if(mc.player==null||mc.level==null)return;List<PokemonInfo> scan=PokemonScanner.scanWild();Set<Integer> live=new HashSet<>();PokemonInfo best=null;for(PokemonInfo p:scan){live.add(p.entityId());if((p.shiny()||p.legendary()||p.mythical()||p.ultraBeast()||p.paradox()||(p.boss()&&RadarSettings.bossAlertsEnabled))&&(best==null||priority(p)>priority(best)||priority(p)==priority(best)&&p.distance()<best.distance()))best=p;if(RadarSettings.alertsEnabled&&(p.shiny()||p.legendary()||p.mythical()||p.ultraBeast()||p.paradox()||(p.boss()&&RadarSettings.bossAlertsEnabled)||target(p))&&seen.add(p.entityId()))alert(mc,p);}seen.retainAll(live);if(best!=null&&(RadarSettings.trackedEntityId==-1||priority(best)>=90))RadarSettings.trackedEntityId=best.entityId();}
private static boolean target(PokemonInfo p){return RadarSettings.targetPokemon.contains(p.name().toLowerCase(java.util.Locale.ROOT));}private static void alert(Minecraft mc,PokemonInfo p){String type=target(p)?"TARGET":p.shiny()?"SHINY":p.legendary()?"LEGENDARY":p.mythical()?"MYTHICAL":p.ultraBeast()?"ULTRA BEAST":p.paradox()?"PARADOX":"BOSS";int color=p.shiny()?0x55FFFF:0xFFD75A;mc.player.displayClientMessage(Component.literal("["+type+"] "+p.name()+" • "+Math.round(p.distance())+"m • "+direction(mc,p)).withColor(color),false);if(!RadarSettings.alertSound)return;double x=mc.player.getX(),y=mc.player.getY(),z=mc.player.getZ();if(p.shiny()){mc.level.playLocalSound(x,y,z,SoundEvents.PLAYER_LEVELUP,SoundSource.MASTER,1f,1.55f,false);mc.level.playLocalSound(x,y,z,SoundEvents.AMETHYST_BLOCK_CHIME,SoundSource.MASTER,.9f,1.8f,false);}else{mc.level.playLocalSound(x,y,z,SoundEvents.NOTE_BLOCK_BELL.value(),SoundSource.MASTER,.9f,.75f,false);mc.level.playLocalSound(x,y,z,SoundEvents.EXPERIENCE_ORB_PICKUP,SoundSource.MASTER,.7f,1f,false);}}
private static String direction(Minecraft mc,PokemonInfo p){double dx=p.pos().getX()+.5-mc.player.getX(),dz=p.pos().getZ()+.5-mc.player.getZ();double a=(Math.toDegrees(Math.atan2(-dx,dz))+360)%360;String[]d={"N","NE","E","SE","S","SW","W","NW"};return d[(int)Math.round(a/45)%8];}}
